1	//! The seam between the server binary and a model crate.
2	//!
3	//! A model line is everything south of the engine contract: config probing,
4	//! its own CLI knobs, and a `launch` that starts scheduler threads and hands
5	//! back a [`LaunchedEngine`]. The server binary holds a feature-gated
6	//! [`ModelLineRegistry`] and does pure dispatch — it never names a model
7	//! crate's option types.
8	//!
9	//! Onboarding a model line means implementing [`ModelLine`] in the model
10	//! crate and adding the instance to the registry in the server binary. No
11	//! other server edits: argument routing, consume-or-reject validation, and
12	//! config detection all derive from the trait.
13	
14	use std::collections::BTreeMap;
15	use std::collections::BTreeSet;
16	use std::path::Path;
17	use std::path::PathBuf;
18	
19	use crate::engine::LaunchedEngine;
20	use crate::vllm::LoraModule;
21	
22	/// Model detection failed. The server branches on [`DetectError::NoMatch`]
23	/// to append a feature-gate hint for families that exist but were compiled
24	/// out; everything else just renders.
25	#[derive(Debug, thiserror::Error)]
26	pub enum DetectError {
27	    #[error("model config claimed by both {first} and {second}")]
28	    Conflict {
29	        first: &'static str,
30	        second: &'static str,
31	    },
32	    #[error(
33	        "no compiled-in model line claims this config (model_type={model_type}, architectures={architectures}); rejections: {}",
34	        rejections.join("; ")
35	    )]
36	    NoMatch {
37	        /// `model_type` from config.json, rendered verbatim (or `missing`).
38	        model_type: String,
39	        /// `architectures` from config.json, rendered verbatim (or `missing`).
40	        architectures: String,
41	        /// One `<line>: <reason>` entry per compiled-in line.
42	        rejections: Vec<String>,
43	    },
44	}
45	
46	/// A CLI-level rejection: the flag set is well-formed for clap but invalid
47	/// for the detected model line.
48	#[derive(Debug, thiserror::Error)]
49	pub enum CliError {
50	    /// A provided flag is neither core, nor shared-and-consumed, nor one of
51	    /// the detected line's own flags.
52	    #[error("--{flag} is not used by {line}")]
53	    UnconsumedFlag { flag: String, line: &'static str },
54	    /// A line-specific cross-flag rule was violated. The message is the
55	    /// user-facing explanation; rules are prose, not a taxonomy.
56	    #[error("{0}")]
57	    Rule(String),
58	}
59	
60	impl CliError {
61	    pub fn rule(message: impl Into<String>) -> Self {
62	        Self::Rule(message.into())
63	    }
64	}
65	
66	/// Flags accepted for every model line regardless of detected type.
67	const CORE_ARGS: &[&str] = &["model_path", "served_model_name", "port"];
68	
69	/// A source argument id and the argument ids it requires.
70	pub type ArgRequirement = (&'static str, &'static [&'static str]);
71	
72	const DEFAULT_MODEL_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../models/Qwen3-4B");
73	
74	/// Shared CLI selector for model lines that can overlap prefill and decode.
75	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, clap::ValueEnum)]
76	pub enum CliDecodeOverlap {
77	    /// One stream; prefill and decode serialize.
78	    #[default]
79	    Off,
80	    /// Two CUDA streams sharing all SMs.
81	    Stream,
82	    /// Green Context SM partition (SM-pinned streams).
83	    #[value(name = "green-ctx")]
84	    GreenCtx,
85	}
86	
87	// CLI flags shared by more than one model line. Each line declares the
88	// subset it reads via `ModelLine::consumed_shared_args`; providing a flag
89	// outside that subset fails validation with a per-line error.
90	// (Regular comment: a doc comment here would override the command about.)
91	#[derive(Debug, clap::Args)]
92	#[allow(clippy::struct_excessive_bools)] // independent CLI flags, not a state machine
93	pub struct SharedArgs {
94	    /// Model directory containing config, tokenizer, and safetensor shards
95	    #[arg(long, default_value = DEFAULT_MODEL_PATH)]
96	    pub model_path: PathBuf,
97	
98	    /// Public model ID returned by the OpenAI API (/v1/models, completion `model`).
99	    /// Defaults to the model path when omitted.
100	    #[arg(long)]
101	    pub served_model_name: Option<String>,
102	
103	    /// Port to listen on
104	    #[arg(long, default_value_t = 8000)]
105	    pub port: u16,
106	
107	    /// Enable CUDA Graph capture/replay on decode path (`--cuda-graph=false` to
108	    /// disable). Rejected for GLM5.2; forced off in Qwen3 LoRA mode; Qwen3.5
109	    /// always captures and rejects `false`; dense Gemma 4 captures per batch
110	    /// bucket while routed checkpoints warn and serve eagerly.
111	    #[arg(long, default_value_t = true, action = clap::ArgAction::Set)]
112	    pub cuda_graph: bool,
113	
114	    /// Dump a live rank-0 decode CUDA Graph during startup. Qwen3 exports its
115	    /// batch-1 SplitKv graph; GLM5.2 exports EP bucket 1 selected by
116	    /// `--moe-topo`. Writes a complete sibling `.dot` for machine inspection
117	    /// and a folded Graphviz PNG at this path. Requires CUDA driver API 12.3
118	    /// or newer for kernel-name inspection.
119	    #[arg(long)]
120	    pub dump_graph_png: Option<PathBuf>,
121	
122	    /// CUDA device ordinal for single-GPU Qwen3/Qwen3.5 loads
123	    #[arg(long, default_value_t = 0)]
124	    pub device_ordinal: usize,
125	
126	    /// Tensor-parallel world size. GLM5.2 supports TP1/EP8 today; TP4/GB300
127	    /// bring-up uses --tp-size=4 --moe-topo=tp4.
128	    #[arg(long, default_value_t = 1)]
129	    pub tp_size: usize,
130	
131	    /// Data-parallel world size. Kimi-K2 and GLM5.2 EP8 default to 8;
132	    /// GLM5.2 TP4 defaults to 1.
133	    #[arg(long)]
134	    pub dp_size: Option<usize>,
135	
136	    /// Enable pegaflow KV offload (host-tier "L2" cache): single-GPU Qwen3,
137	    /// or GLM5.2 DP8 (one pool shared by all 8 ranks under one namespace).
138	    /// Sealed KV blocks are saved to host pinned memory and restored into
139	    /// HBM before prefill when a prompt's prefix has fallen out of the GPU
140	    /// cache. GLM5.2 requires the prefix cache: incompatible with
141	    /// --no-prefix-cache and speculative decoding.
142	    #[arg(long, default_value_t = false)]
143	    pub kv_offload: bool,
144	
145	    /// Host pinned-memory pool size for the KV offload tier, in GiB. pegaflow
146	    /// allocates the whole pool up front, so RSS reflects this at startup.
147	    #[arg(long, default_value_t = 8.0, value_parser = parse_offload_gib)]
148	    pub kv_offload_host_gib: f64,
149	
150	    /// Back the KV offload pool with 2 MiB hugepages. The box must hold a
151	    /// reservation covering the pool (`HugePages_Total` in /proc/meminfo;
152	    /// `echo N > /proc/sys/vm/nr_hugepages` as root) — allocation fails at
153	    /// startup otherwise.
154	    #[arg(long, default_value_t = false)]
155	    pub kv_offload_hugepages: bool,
156	
157	    /// Join the cross-instance KV P2P mesh: pegaflow MetaServer gRPC address
158	    /// (e.g. `http://127.0.0.1:50056`). Saved block hashes register there and
159	    /// missing prefixes are pulled from peer instances over RDMA — the P/D
160	    /// disaggregation data plane. Requires --kv-offload, --kv-p2p-advertise-addr
161	    /// and --kv-p2p-nics.
162	    #[arg(long)]
163	    pub kv_p2p_metaserver_addr: Option<String>,
164	
165	    /// This instance's routable IP:port for KV P2P — a literal socket address
166	    /// (it is also the embedded transfer-service bind address, so hostnames
167	    /// are rejected at startup). Peers dial it for RDMA handshakes and block
168	    /// queries. Must be reachable by every peer; not 0.0.0.0.
169	    #[arg(long)]
170	    pub kv_p2p_advertise_addr: Option<String>,
171	
172	    /// RDMA NIC device names for KV P2P (e.g. `mlx5_0`), comma-separated.
173	    #[arg(long, value_delimiter = ',')]
174	    pub kv_p2p_nics: Vec<String>,
175	
176	    /// vLLM-style no-prefix-cache. Without --kv-offload it disables prefix
177	    /// matching outright (every prefill recomputes the full prompt). With
178	    /// --kv-offload it is the pure-L2 mode: no cross-request HBM reuse, so every
179	    /// prefix is restored from the host tier — for measuring the L2 TTFT win.
180	    #[arg(long, default_value_t = false)]
181	    pub no_prefix_cache: bool,
182	
183	    /// Speculative drafter model path: Qwen3 DFlash/DSpark decoding, or the
184	    /// GLM5.2 DSpark drafter (greedy AND sampled requests speculate;
185	    /// per-request accept stats logged). For Qwen3: single-GPU greedy only;
186	    /// incompatible with --enable-lora and --kv-offload, and forces the
187	    /// prefix cache off (it needs clean target hidden states).
188	    #[arg(long = "dflash-draft-model-path")]
189	    pub dflash_draft_model_path: Option<PathBuf>,
190	
191	    /// Cap on total prompt tokens forwarded in one scheduler step. Qwen3 and
