221	    /// Line-specific rules live in each line's [`ModelLine::validate`].
222	    pub fn validate(&self, provided: &BTreeSet<String>) -> Result<(), CliError> {
223	        if self.dump_graph_png.is_some() && !self.cuda_graph {
