452	/// The server binary's fixed list of compiled-in model lines.
453	pub struct ModelLineRegistry {
454	    entries: Vec<LineEntry>,
455	    requirements: BTreeMap<&'static str, &'static [&'static str]>,
456	}
457	
458	impl ModelLineRegistry {
459	    /// Validates CLI ownership explicitly because Clap's equivalent schema
460	    /// assertions are disabled in release builds.
461	    pub fn new(lines: Vec<&'static dyn ModelLine>) -> Self {
462	        let shared_cmd = SharedArgs::augment_args(clap::Command::new("probe"));
463	        let mut claims = RegistryClaims::default();
464	        claims.register_command(&shared_cmd, ArgOwner::Shared);
465	        for id in CORE_ARGS {
466	            assert!(
467	                claims.is_shared_id(id),
468	                "CORE_ARGS contains unknown SharedArgs flag id {id:?}"
469	            );
470	        }
471	        let mut pending_requirements = SHARED_ARG_REQUIREMENTS
472	            .iter()
473	            .map(|&(source, targets)| (ArgOwner::Shared, source, targets))
474	            .collect::<Vec<_>>();
475	        let mut entries = Vec::with_capacity(lines.len());
476	        let mut line_names = BTreeSet::new();
477	        for line in lines {
478	            let name = line.name();
479	            assert!(
480	                line_names.insert(name),
481	                "duplicate model line name {name:?}"
482	            );
483	            let owner = ArgOwner::Line(name);
484	            entries.push(register_line(line, owner, &mut claims));
485	            pending_requirements.extend(
486	                line.arg_requirements()
487	                    .iter()
488	                    .map(|&(source, targets)| (owner, source, targets)),
489	            );
490	        }
491	        let mut requirements = BTreeMap::new();
492	        for (owner, source, targets) in pending_requirements {
493	            claims.validate_requirement(owner, source, targets);
494	            assert!(
495	                requirements.insert(source, targets).is_none(),
496	                "{owner} declares requirements more than once for flag id {source:?}"
497	            );
498	        }
499	        Self {
500	            entries,
501	            requirements,
502	        }
503	    }
504	
505	    /// The full server command: shared flags plus every line's exclusive
506	    /// flags, so `--help` and parsing don't depend on the detected model.
507	    pub fn build_command(&self, cmd: clap::Command) -> clap::Command {
508	        let mut cmd = SharedArgs::augment_args(cmd);
509	        for entry in &self.entries {
510	            cmd = entry.line.augment_cli(cmd);
511	        }
512	        // `mut_arg` re-appends each source and would reorder `--help`.
513	        cmd.mut_args(|arg| {
514	            let Some(targets) = self.requirements.get(arg.get_id().as_str()) else {
515	                return arg;
516	            };
517	            arg.requires_all(targets.iter().copied())
518	        })
519	    }
520	
521	    /// Find the unique line that claims this `config.json`. On
522	    /// [`DetectError::NoMatch`] the caller may prepend a hint for families
523	    /// that exist but were compiled out.
524	    pub fn detect(
525	        &self,
526	        config: &serde_json::Value,
527	    ) -> Result<&'static dyn ModelLine, DetectError> {
528	        let mut rejections = Vec::new();
529	        let mut claimed: Option<&'static dyn ModelLine> = None;
530	        for entry in &self.entries {
531	            match entry.line.probe(config) {
532	                Ok(()) => match claimed {
533	                    None => claimed = Some(entry.line),
534	                    Some(prev) => {
535	                        return Err(DetectError::Conflict {
536	                            first: prev.name(),
537	                            second: entry.line.name(),
538	                        });
539	                    }
540	                },
541	                Err(reason) => rejections.push(format!("{}: {reason}", entry.line.name())),
542	            }
543	        }
544	        claimed.ok_or_else(|| {
545	            let render = |key: &str| {
546	                config
547	                    .get(key)
548	                    .map_or_else(|| "missing".to_string(), std::string::ToString::to_string)
549	            };
550	            DetectError::NoMatch {
551	                model_type: render("model_type"),
552	                architectures: render("architectures"),
553	                rejections,
554	            }
555	        })
556	    }
557	
558	    /// Consume-or-reject: every explicitly provided flag must be a core flag,
559	    /// a shared flag the detected line consumes, or one of the line's own.
560	    pub fn validate_provided(
561	        &self,
562	        detected: &'static dyn ModelLine,
563	        provided: &BTreeSet<String>,
564	        cmd: &clap::Command,
565	    ) -> Result<(), CliError> {
566	        let entry = self
567	            .entries
568	            .iter()
569	            .find(|entry| std::ptr::eq(entry.line, detected))
570	            .expect("detected line came from this registry");
571	        for id in provided {
572	            let id = id.as_str();
573	            if CORE_ARGS.contains(&id)
574	                || detected.consumed_shared_args().contains(&id)
575	                || entry.own_ids.contains(id)
576	            {
577	                continue;
578	            }
579	            return Err(CliError::UnconsumedFlag {
580	                flag: long_flag(cmd, id),
581	                line: detected.name(),
582	            });
583	        }
584	        Ok(())
585	    }
586	}
587	
588	fn long_flag(cmd: &clap::Command, id: &str) -> String {
589	    cmd.get_arguments()
590	        .find(|arg| arg.get_id() == id)
591	        .and_then(clap::Arg::get_long)
592	        .map_or_else(|| id.to_owned(), str::to_owned)
593	}
594	
595	/// Arg ids the user set explicitly (command line or env), for consume-or-reject.
596	pub fn provided_args(matches: &clap::ArgMatches, cmd: &clap::Command) -> BTreeSet<String> {
597	    // matches.ids() also yields clap's synthetic group ids; keep only real args.
598	    let real: BTreeSet<&str> = cmd
599	        .get_arguments()
600	        .map(|arg| arg.get_id().as_str())
601	        .collect();
602	    matches
603	        .ids()
604	        .map(clap::Id::as_str)
605	        .filter(|id| real.contains(id))
606	        .filter(|id| {
607	            matches!(
608	                matches.value_source(id),
609	                Some(
610	                    clap::parser::ValueSource::CommandLine | clap::parser::ValueSource::EnvVariable
611	                )
612	            )
613	        })
614	        .map(str::to_owned)
615	        .collect()
616	}
