620	/// Test helper: parse `argv` against shared flags plus one line's flags, the
621	/// way the server binary does for a detected line. Exposed for model-crate
622	/// unit tests; not a serving entry point.
623	pub fn parse_for_line(
624	    line: &'static dyn ModelLine,
625	    argv: &[&str],
626	) -> anyhow::Result<(SharedArgs, clap::ArgMatches, BTreeSet<String>)> {
627	    use clap::FromArgMatches;
628	    let registry = ModelLineRegistry::new(vec![line]);
629	    let cmd = registry.build_command(clap::Command::new("pegainfer"));
630	    let matches = cmd.clone().try_get_matches_from(argv)?;
631	    let shared = SharedArgs::from_arg_matches(&matches)?;
632	    let provided = provided_args(&matches, &cmd);
633	    registry.validate_provided(line, &provided, &cmd)?;
634	    shared.validate(&provided)?;
635	    Ok((shared, matches, provided))
636	}
