151	    })?;
152	
153	    registry.validate_provided(line, &provided, &cmd)?;
154	    shared.validate(&provided)?;
155	    let ctx = LaunchContext {
156	        model_path: &shared.model_path,
157	        config: &config,
158	        shared: &shared,
159	        matches: &matches,
160	    };
161	    line.validate(&ctx, &provided)?;
162	    let plan = line.serve_plan(&ctx)?;
163	
164	    info!("=== pegainfer - {} (GPU) ===", line.name());
165	    info!("Loading engine...");
166	    let start = Instant::now();
167	    info!(
168	        "Runtime: model_path={}, user-set flags {provided:?}",
169	        shared.model_path.display(),
170	    );
171	
172	    let model_path = shared.model_path.clone();
173	    let served_model_name = shared.served_model_name.clone();
174	    let port = shared.port;
175	
176	    // Engine load (weights → GPU) runs on a blocking thread so the HTTP
177	    // frontend (tokenizer, chat templates) loads concurrently. The frontend
178	    // binds only after the engine registers, so readiness is unchanged.
179	    let engine_load = tokio::task::spawn_blocking(move || -> anyhow::Result<LaunchedEngine> {
180	        let ctx = LaunchContext {
181	            model_path: &shared.model_path,
182	            config: &config,
183	            shared: &shared,
184	            matches: &matches,
